/// Every variant of accordion: the core values by name, the values a design system added in [extra].
/// Look one up with `variants[key]`; the lookup is total.
@immutable
class TanreiAccordionVariants {
  const TanreiAccordionVariants({
    required this.plain,
    required this.outlined,
    this.extra = const <TanreiAccordionVariant, TanreiAccordionVariantTokens>{},
  });

  /// `comp.accordion` variant `plain`
  final TanreiAccordionVariantTokens plain;
  /// `comp.accordion` variant `outlined`
  final TanreiAccordionVariantTokens outlined;

  /// The variants a design system added to the core vocabulary.
  final Map<TanreiAccordionVariant, TanreiAccordionVariantTokens> extra;

  /// A copy with the given tokens replaced. The entries of [extra] are added to the existing ones (and replace
  /// those with the same key): a copy never loses a value the design system added.
  TanreiAccordionVariants copyWith({
    TanreiAccordionVariantTokens? plain,
    TanreiAccordionVariantTokens? outlined,
    Map<TanreiAccordionVariant, TanreiAccordionVariantTokens>? extra,
  }) => TanreiAccordionVariants(
        plain: plain ?? this.plain,
        outlined: outlined ?? this.outlined,
        extra: extra == null ? this.extra : <TanreiAccordionVariant, TanreiAccordionVariantTokens>{...this.extra, ...extra},
      );

  /// The tokens of [variant].
  ///
  /// A variant this design system does not have resolves to [plain], the default; debug builds report it
  /// through [debugTanreiReportUnknownValue] and release builds stay silent.
  TanreiAccordionVariantTokens operator [](TanreiAccordionVariant variant) => switch (variant.name) {
        'plain' => plain,
        'outlined' => outlined,
        _ => extra[variant] ?? _fallback(variant),
      };

  /// Whether this design system has [variant].
  bool has(TanreiAccordionVariant variant) => TanreiAccordionVariant.core.contains(variant) || extra.containsKey(variant);

  /// Every variant this design system has: the core values, then the added ones.
  List<TanreiAccordionVariant> get keys => <TanreiAccordionVariant>[...TanreiAccordionVariant.core, ...extra.keys];

  TanreiAccordionVariantTokens _fallback(TanreiAccordionVariant variant) {
    assert(() {
      debugTanreiReportUnknownValue('accordion variant', variant.name, 'plain');
      return true;
    }());
    return plain;
  }
}

