  /// through [debugTanreiReportUnknownValue] and release builds stay silent.
  TanreiChipSizeTokens operator [](TanreiChipSize size) => switch (size.name) {
        'small' => small,
        'medium' => medium,
        _ => extra[size] ?? _fallback(size),
      };

  /// Whether this design system has [size].
  bool has(TanreiChipSize size) => TanreiChipSize.core.contains(size) || extra.containsKey(size);

  /// Every size this design system has: the core values, then the added ones.
  List<TanreiChipSize> get keys => <TanreiChipSize>[...TanreiChipSize.core, ...extra.keys];

  TanreiChipSizeTokens _fallback(TanreiChipSize size) {
