/// Every condition of date-time-picker: the core values by name, the values a design system added in [extra].
/// Look one up with `conditions[key]`; the lookup is total.
@immutable
class TanreiDateTimePickerConditions {
  const TanreiDateTimePickerConditions({
    required this.unselected,
    required this.selected,
    this.extra = const <TanreiDateTimePickerCondition, TanreiDateTimePickerConditionTokens>{},
  });

  /// `comp.date-time-picker` condition `unselected`
  final TanreiDateTimePickerConditionTokens unselected;
  /// `comp.date-time-picker` condition `selected`
  final TanreiDateTimePickerConditionTokens selected;

  /// The conditions a design system added to the core vocabulary.
  final Map<TanreiDateTimePickerCondition, TanreiDateTimePickerConditionTokens> extra;

  /// A copy with the given tokens replaced. The entries of [extra] are added to the existing ones (and replace
  /// those with the same key): a copy never loses a value the design system added.
  TanreiDateTimePickerConditions copyWith({
    TanreiDateTimePickerConditionTokens? unselected,
    TanreiDateTimePickerConditionTokens? selected,
    Map<TanreiDateTimePickerCondition, TanreiDateTimePickerConditionTokens>? extra,
  }) => TanreiDateTimePickerConditions(
        unselected: unselected ?? this.unselected,
        selected: selected ?? this.selected,
        extra: extra == null ? this.extra : <TanreiDateTimePickerCondition, TanreiDateTimePickerConditionTokens>{...this.extra, ...extra},
      );

  /// The tokens of [condition].
  ///
  /// A condition this design system does not have resolves to [unselected], the default; debug builds report it
  /// through [debugTanreiReportUnknownValue] and release builds stay silent.
  TanreiDateTimePickerConditionTokens operator [](TanreiDateTimePickerCondition condition) => switch (condition.name) {
        'unselected' => unselected,
        'selected' => selected,
        _ => extra[condition] ?? _fallback(condition),
      };

  /// Whether this design system has [condition].
  bool has(TanreiDateTimePickerCondition condition) => TanreiDateTimePickerCondition.core.contains(condition) || extra.containsKey(condition);

  /// Every condition this design system has: the core values, then the added ones.
  List<TanreiDateTimePickerCondition> get keys => <TanreiDateTimePickerCondition>[...TanreiDateTimePickerCondition.core, ...extra.keys];

  TanreiDateTimePickerConditionTokens _fallback(TanreiDateTimePickerCondition condition) {
    assert(() {
      debugTanreiReportUnknownValue('date-time-picker condition', condition.name, 'unselected');
      return true;
    }());
    return unselected;
  }
}

