/// Every size of input-box: the core values by name, the values a design system added in [extra].
/// Look one up with `sizes[key]`; the lookup is total.
@immutable
class TanreiInputBoxSizes {
  const TanreiInputBoxSizes({
    required this.small,
    required this.medium,
    required this.large,
    this.extra = const <TanreiInputBoxSize, TanreiInputBoxSizeTokens>{},
  });

  /// `comp.input-box` size `small`
  final TanreiInputBoxSizeTokens small;
  /// `comp.input-box` size `medium`
  final TanreiInputBoxSizeTokens medium;
  /// `comp.input-box` size `large`
  final TanreiInputBoxSizeTokens large;

  /// The sizes a design system added to the core vocabulary.
  final Map<TanreiInputBoxSize, TanreiInputBoxSizeTokens> extra;

  /// A copy with the given tokens replaced. The entries of [extra] are added to the existing ones (and replace
  /// those with the same key): a copy never loses a value the design system added.
  TanreiInputBoxSizes copyWith({
    TanreiInputBoxSizeTokens? small,
    TanreiInputBoxSizeTokens? medium,
    TanreiInputBoxSizeTokens? large,
    Map<TanreiInputBoxSize, TanreiInputBoxSizeTokens>? extra,
  }) => TanreiInputBoxSizes(
        small: small ?? this.small,
        medium: medium ?? this.medium,
        large: large ?? this.large,
        extra: extra == null ? this.extra : <TanreiInputBoxSize, TanreiInputBoxSizeTokens>{...this.extra, ...extra},
      );

  /// The tokens of [size].
  ///
  /// A size this design system does not have resolves to [medium], the default; debug builds report it
  /// through [debugTanreiReportUnknownValue] and release builds stay silent.
  TanreiInputBoxSizeTokens operator [](TanreiInputBoxSize size) => switch (size.name) {
        'small' => small,
        'medium' => medium,
        'large' => large,
        _ => extra[size] ?? _fallback(size),
      };

  /// Whether this design system has [size].
  bool has(TanreiInputBoxSize size) => TanreiInputBoxSize.core.contains(size) || extra.containsKey(size);

  /// Every size this design system has: the core values, then the added ones.
  List<TanreiInputBoxSize> get keys => <TanreiInputBoxSize>[...TanreiInputBoxSize.core, ...extra.keys];

  TanreiInputBoxSizeTokens _fallback(TanreiInputBoxSize size) {
    assert(() {
      debugTanreiReportUnknownValue('input-box size', size.name, 'medium');
      return true;
    }());
    return medium;
  }
}

