/// Every condition of menu: the core values by name, the values a design system added in [extra].
/// Look one up with `conditions[key]`; the lookup is total.
@immutable
class TanreiMenuConditions {
  const TanreiMenuConditions({
    required this.unselected,
    required this.selected,
    required this.destructive,
    required this.expanded,
    this.extra = const <TanreiMenuCondition, TanreiMenuConditionTokens>{},
  });

  /// `comp.menu` condition `unselected`
  final TanreiMenuConditionTokens unselected;
  /// `comp.menu` condition `selected`
  final TanreiMenuConditionTokens selected;
  /// `comp.menu` condition `destructive`
  final TanreiMenuConditionTokens destructive;
  /// `comp.menu` condition `expanded`
  final TanreiMenuConditionTokens expanded;

  /// The conditions a design system added to the core vocabulary.
  final Map<TanreiMenuCondition, TanreiMenuConditionTokens> extra;

  /// A copy with the given tokens replaced. The entries of [extra] are added to the existing ones (and replace
  /// those with the same key): a copy never loses a value the design system added.
  TanreiMenuConditions copyWith({
    TanreiMenuConditionTokens? unselected,
    TanreiMenuConditionTokens? selected,
    TanreiMenuConditionTokens? destructive,
    TanreiMenuConditionTokens? expanded,
    Map<TanreiMenuCondition, TanreiMenuConditionTokens>? extra,
  }) => TanreiMenuConditions(
        unselected: unselected ?? this.unselected,
        selected: selected ?? this.selected,
        destructive: destructive ?? this.destructive,
        expanded: expanded ?? this.expanded,
        extra: extra == null ? this.extra : <TanreiMenuCondition, TanreiMenuConditionTokens>{...this.extra, ...extra},
      );

  /// The tokens of [condition].
  ///
  /// A condition this design system does not have resolves to [unselected], the default; debug builds report it
  /// through [debugTanreiReportUnknownValue] and release builds stay silent.
  TanreiMenuConditionTokens operator [](TanreiMenuCondition condition) => switch (condition.name) {
        'unselected' => unselected,
        'selected' => selected,
        'destructive' => destructive,
        'expanded' => expanded,
        _ => extra[condition] ?? _fallback(condition),
      };

  /// Whether this design system has [condition].
  bool has(TanreiMenuCondition condition) => TanreiMenuCondition.core.contains(condition) || extra.containsKey(condition);

  /// Every condition this design system has: the core values, then the added ones.
  List<TanreiMenuCondition> get keys => <TanreiMenuCondition>[...TanreiMenuCondition.core, ...extra.keys];

  TanreiMenuConditionTokens _fallback(TanreiMenuCondition condition) {
    assert(() {
      debugTanreiReportUnknownValue('menu condition', condition.name, 'unselected');
      return true;
    }());
    return unselected;
  }
}

