/// Every part of table: the core values by name, the values a design system added in [extra].
/// Look one up with `parts[key]`; the lookup is total.
@immutable
class TanreiTableParts {
  const TanreiTableParts({
    required this.sort,
    required this.sorted,
    this.extra = const <TanreiTablePart, TanreiTablePartTokens>{},
  });

  /// `comp.table` part `sort`
  final TanreiTablePartTokens sort;
  /// `comp.table` part `sorted`
  final TanreiTablePartTokens sorted;

  /// The parts a design system added to the core vocabulary.
  final Map<TanreiTablePart, TanreiTablePartTokens> extra;

  /// A copy with the given tokens replaced. The entries of [extra] are added to the existing ones (and replace
  /// those with the same key): a copy never loses a value the design system added.
  TanreiTableParts copyWith({
    TanreiTablePartTokens? sort,
    TanreiTablePartTokens? sorted,
    Map<TanreiTablePart, TanreiTablePartTokens>? extra,
  }) => TanreiTableParts(
        sort: sort ?? this.sort,
        sorted: sorted ?? this.sorted,
        extra: extra == null ? this.extra : <TanreiTablePart, TanreiTablePartTokens>{...this.extra, ...extra},
      );

  /// The tokens of [part].
  ///
  /// A part this design system does not have resolves to [sort], the default; debug builds report it
  /// through [debugTanreiReportUnknownValue] and release builds stay silent.
  TanreiTablePartTokens operator [](TanreiTablePart part_) => switch (part_.name) {
        'sort' => sort,
        'sorted' => sorted,
        _ => extra[part_] ?? _fallback(part_),
      };

  /// Whether this design system has [part].
  bool has(TanreiTablePart part_) => TanreiTablePart.core.contains(part_) || extra.containsKey(part_);

  /// Every part this design system has: the core values, then the added ones.
  List<TanreiTablePart> get keys => <TanreiTablePart>[...TanreiTablePart.core, ...extra.keys];

  TanreiTablePartTokens _fallback(TanreiTablePart part_) {
    assert(() {
      debugTanreiReportUnknownValue('table part', part_.name, 'sort');
      return true;
    }());
    return sort;
  }
}

