  TanreiTreeViewDensityTokens _fallback(TanreiTreeViewDensity density) {
    assert(() {
      debugTanreiReportUnknownValue('tree-view density', density.name, 'regular');
      return true;
    }());
    return regular;
  }
}

/// The tokens of tree-view that vary by interaction state but not by variant.
@immutable
class TanreiTreeViewStateTokens {
  const TanreiTreeViewStateTokens({
    required this.opacity,
  });

  /// `comp.tree-view.<state>.opacity`
  final double opacity;

  /// A copy with the given tokens replaced.
  TanreiTreeViewStateTokens copyWith({
    double? opacity,
  }) => TanreiTreeViewStateTokens(
        opacity: opacity ?? this.opacity,
      );
}

/// `comp.tree-view.*`
@immutable
class TanreiTreeViewTokens {
  const TanreiTreeViewTokens({
    required this.containerShape,
    required this.guideColor,
    required this.guideWidth,
    required this.motionDisclosureDuration,
    required this.motionDisclosureEasing,
    required this.motionFeedbackDuration,
    required this.motionStateDuration,
    required this.motionStateEasing,
    required this.supportingTextTypescale,
    required this.trailingTextTypescale,
    required this.conditions,
    required this.densitys,
    required this.hovered,
    required this.focused,
    required this.pressed,
    required this.disabled,
  });

  /// `comp.tree-view.container-shape`
  final double containerShape;
  /// `comp.tree-view.guide-color`
  final TanreiPaint guideColor;
  /// `comp.tree-view.guide-width`
  final double guideWidth;
  /// `comp.tree-view.motion-disclosure-duration`
  final int motionDisclosureDuration;
  /// `comp.tree-view.motion-disclosure-easing`
  final TanreiCubicBezier motionDisclosureEasing;
  /// `comp.tree-view.motion-feedback-duration`
  final int motionFeedbackDuration;
  /// `comp.tree-view.motion-state-duration`
  final int motionStateDuration;
  /// `comp.tree-view.motion-state-easing`
  final TanreiCubicBezier motionStateEasing;
  /// `comp.tree-view.supporting-text-typescale`
  final TanreiTextStyle supportingTextTypescale;
  /// `comp.tree-view.trailing-text-typescale`
  final TanreiTextStyle trailingTextTypescale;
  /// The `condition` axis: `conditions[condition]`.
  final TanreiTreeViewConditions conditions;
  /// The `density` axis: `densitys[density]`.
  final TanreiTreeViewDensitys densitys;
  /// `comp.tree-view.hovered.*`
  final TanreiTreeViewStateTokens hovered;
  /// `comp.tree-view.focused.*`
  final TanreiTreeViewStateTokens focused;
  /// `comp.tree-view.pressed.*`
  final TanreiTreeViewStateTokens pressed;
  /// `comp.tree-view.disabled.*`
  final TanreiTreeViewStateTokens disabled;

  /// A copy with the given tokens replaced.
  TanreiTreeViewTokens copyWith({
    double? containerShape,
    TanreiPaint? guideColor,
    double? guideWidth,
    int? motionDisclosureDuration,
    TanreiCubicBezier? motionDisclosureEasing,
    int? motionFeedbackDuration,
    int? motionStateDuration,
    TanreiCubicBezier? motionStateEasing,
    TanreiTextStyle? supportingTextTypescale,
    TanreiTextStyle? trailingTextTypescale,
    TanreiTreeViewConditions? conditions,
    TanreiTreeViewDensitys? densitys,
    TanreiTreeViewStateTokens? hovered,
    TanreiTreeViewStateTokens? focused,
    TanreiTreeViewStateTokens? pressed,
    TanreiTreeViewStateTokens? disabled,
  }) => TanreiTreeViewTokens(
        containerShape: containerShape ?? this.containerShape,
        guideColor: guideColor ?? this.guideColor,
        guideWidth: guideWidth ?? this.guideWidth,
        motionDisclosureDuration: motionDisclosureDuration ?? this.motionDisclosureDuration,
        motionDisclosureEasing: motionDisclosureEasing ?? this.motionDisclosureEasing,
        motionFeedbackDuration: motionFeedbackDuration ?? this.motionFeedbackDuration,
        motionStateDuration: motionStateDuration ?? this.motionStateDuration,
        motionStateEasing: motionStateEasing ?? this.motionStateEasing,
        supportingTextTypescale: supportingTextTypescale ?? this.supportingTextTypescale,
        trailingTextTypescale: trailingTextTypescale ?? this.trailingTextTypescale,
        conditions: conditions ?? this.conditions,
        densitys: densitys ?? this.densitys,
        hovered: hovered ?? this.hovered,
        focused: focused ?? this.focused,
        pressed: pressed ?? this.pressed,
        disabled: disabled ?? this.disabled,
      );

  /// The variant-independent tokens of [state], or null for a state that has none (`enabled`: the
  /// resting tokens of this class apply).
  TanreiTreeViewStateTokens? stateTokens(TanreiInteractionState state) => switch (state) {
        TanreiInteractionState.enabled => null,
        TanreiInteractionState.hovered => hovered,
        TanreiInteractionState.focused => focused,
        TanreiInteractionState.pressed => pressed,
        TanreiInteractionState.disabled => disabled,
      };
}

